const existingBlog = new Set(existing.map(u=>u.replace("/blog/","")));
const money = new Set(["/pricing","/vps","/game-servers","/rust-server-hosting","/minecraft-server-hosting","/discord-bot-hosting","/docker-hosting","/nodejs-hosting","/n8n-hosting","/nextcloud-hosting","/vpn-server-hosting","/wordpress-vps-hosting","/web-hosting","/business-email","/domains","/migrate","/security","/developers","/block-storage","/free-vps","/cheap-vps-hosting","/affordable-vps-hosting","/best-value-vps","/compare","/register"]);
