console.log("Found in DB:", rows.length);
let problems = [];
const cat = {};
for (const r of rows) {
  const words = r.body.split(/\s+/).filter(Boolean).length;
  const shots = (r.body.match(/\{\{SCREENSHOT\}\}/g)||[]).length;
  cat[r.category] = (cat[r.category]||0)+1;
  // extract markdown links
  const links = [...r.body.matchAll(/\]\((\/[^)]+)\)/g)].map(m=>m[1]);
  const internalLinks = links.length;
  // validate each link
  for (const l of links) {
    if (money.has(l)) continue;
    if (l.startsWith("/blog/")) {
      const s = l.replace("/blog/","");
      if (existingBlog.has(s) || sibling.has(s)) continue;
      problems.push(`${r.slug}: BAD blog link ${l}`);
    } else {
      // non-blog, non-money path
      problems.push(`${r.slug}: UNKNOWN path ${l}`);
    }
  }
  if (words < 1000) problems.push(`${r.slug}: SHORT ${words}w`);
  if (words > 1750) problems.push(`${r.slug}: LONG ${words}w`);
  if (shots < 1 || shots > 2) problems.push(`${r.slug}: SCREENSHOT count ${shots}`);
  if (r.seoTitle.length > 60) problems.push(`${r.slug}: seoTitle ${r.seoTitle.length} chars`);
  if (r.seoDescription.length > 155) problems.push(`${r.slug}: seoDesc ${r.seoDescription.length} chars`);
  if (internalLinks < 3) problems.push(`${r.slug}: only ${internalLinks} links`);
}
console.log("Category breakdown:", cat);
console.log("Problems:", problems.length ? "\n - "+problems.join("\n - ") : "NONE");
await db.$disconnect();
EOF
